//! End-to-end session signing against the real-world fixture and the local
//! PKCS#12 test container.
//!
//! `leaf-aes256.pfx` is generated by
//! `crates/pdfxi-security/tests/fixtures/pfx/generate.ps1` with the public
//! password `pdfxi-test-pfx`. The container holds a private key, so it is
//! never committed and the end-to-end test is `#[ignore]`d, matching
//! `crates/pdfxi-security/tests/pfx_signing.rs`. Run it with:
//!
//! ```text
//! cargo test -p pdfxi-document --test signing -- --ignored --nocapture
//! ```
//!
//! The test proves the ADR 0010 signing contract: the original fixture bytes
//! stay the exact prefix of the signed file, the signature is a separate
//! incremental revision, the session saves and reopens it with PDFXI's own
//! parser (page count and page-1 text unchanged), `verify_signature` reports a
//! fully valid signature covering the whole file, and one flipped byte inside
//! the signed range is reported as `Tampered`.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use pdfxi_document::DocumentSession;
use pdfxi_security::{SignOptions, SignatureStatus, SigningIdentity, verify_signature};

/// Public password used by `generate.ps1`; not a secret.
const PASSWORD: &str = "pdfxi-test-pfx";
/// Fixed signing time so the test is deterministic.
const SIGNING_TIME: u64 = 1_700_000_000;

/// Return the workspace root.
fn workspace_root() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .expect("crates/pdfxi-document lives under the workspace root")
}

/// Return the absolute path of a real-world fixture.
fn fixture(name: &str) -> PathBuf {
    workspace_root()
        .join("fixtures")
        .join("realworld")
        .join(name)
}

/// Return the absolute path of a generated PKCS#12 fixture.
fn pfx(name: &str) -> PathBuf {
    workspace_root()
        .join("crates")
        .join("pdfxi-security")
        .join("tests")
        .join("fixtures")
        .join("pfx")
        .join(name)
}

/// A per-test temporary directory that removes itself on drop.
struct TempDir {
    path: PathBuf,
}

impl TempDir {
    fn new(label: &str) -> Self {
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let sequence = COUNTER.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir()
            .join("pdfxi-document-signing")
            .join(format!("{label}-{}-{sequence}", std::process::id()));
        fs::create_dir_all(&path).expect("create temporary directory");
        Self { path }
    }

    fn join(&self, name: &str) -> PathBuf {
        self.path.join(name)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}

/// Sign, save, reopen, verify and tamper with the real Excel sample.
#[test]
#[ignore = "requires the local test PFX from crates/pdfxi-security/tests/fixtures/pfx/generate.ps1 (public password pdfxi-test-pfx); private keys are never committed"]
fn session_signs_saves_reopens_and_detects_tampering() {
    let original =
        fs::read(fixture("microsoft-excel-2019-sample.pdf")).expect("read the real-world fixture");
    let dir = TempDir::new("sign");
    let path = dir.join("microsoft-excel-2019-sample.pdf");
    fs::write(&path, &original).expect("copy the fixture into a temporary directory");

    let mut session = DocumentSession::open(&path).expect("open the fixture");
    let page_count = session.document().page_count().expect("page count");
    let page_text = session.document().page_text(0).expect("page text");
    assert!(
        page_text.contains("amber compass lantern"),
        "page 1 text was {page_text:?}"
    );
    assert!(!session.is_dirty());
    assert_eq!(session.revision_count(), 0);

    let container = fs::read(pfx("leaf-aes256.pfx")).unwrap_or_else(|error| {
        panic!(
            "read {}: {error}; run crates/pdfxi-security/tests/fixtures/pfx/generate.ps1 first",
            pfx("leaf-aes256.pfx").display()
        )
    });
    let identity =
        SigningIdentity::from_pfx(&container, PASSWORD).expect("import the AES-256 test identity");
    let options = SignOptions {
        signing_time_unix: Some(SIGNING_TIME),
        reason: Some("PDFXI session signing test".to_owned()),
        ..SignOptions::default()
    };

    let report = session
        .sign(&identity, &options)
        .expect("sign through the session");

    // The report identifies the signer and covers the whole signed file.
    assert!(
        report
            .signer_subject()
            .contains("PDFXI Test Signing Identity"),
        "unexpected signer subject: {}",
        report.signer_subject()
    );
    assert_eq!(report.signing_time_unix(), SIGNING_TIME);
    let [start, contents_start, contents_end, remaining] = report.byte_range();
    assert_eq!(start, 0, "the first signed range must start at byte 0");
    assert!(contents_start < contents_end, "empty /Contents window");
    assert_eq!(
        contents_end + remaining,
        session.bytes().len(),
        "the signed ranges must cover the whole signed file"
    );
    assert_eq!(
        report.appended_bytes(),
        session.bytes().len() - original.len(),
        "the signature must be exactly one appended revision"
    );

    // The bytes before the signature are preserved byte for byte, which is
    // what keeps any earlier signature valid.
    assert_eq!(
        &session.bytes()[..original.len()],
        original.as_slice(),
        "the original fixture must stay the exact prefix"
    );
    assert_eq!(session.revision_count(), 1);
    assert!(session.can_undo());
    assert!(!session.can_redo());
    assert!(session.is_dirty());

    // Save, then reopen the saved bytes with PDFXI's own parser.
    session.save().expect("save the signed document");
    assert!(!session.is_dirty());
    let saved = fs::read(&path).expect("read the saved signed file");
    assert_eq!(saved, session.bytes(), "save must write the signed bytes");

    let reopened = DocumentSession::open_bytes(&saved).expect("reopen the signed bytes");
    assert_eq!(
        reopened.document().page_count().expect("page count"),
        page_count,
        "signing must not change the page count"
    );
    assert_eq!(
        reopened.document().page_text(0).expect("page 1 text"),
        page_text,
        "signing must not change page 1 text"
    );

    // The saved signature is fully valid and covers the entire file.
    let verification = verify_signature(&saved).expect("verify the saved signature");
    assert_eq!(verification.status(), SignatureStatus::Valid);
    assert!(verification.signature_valid());
    assert!(verification.bytes_match());
    assert!(verification.covers_entire_file());
    assert!(!verification.appended_after_signature());
    assert!(verification.is_fully_valid());
    assert_eq!(verification.byte_range(), report.byte_range());
    assert_eq!(verification.signing_time_unix(), Some(SIGNING_TIME));
    assert!(
        verification
            .signer_subject()
            .contains("PDFXI Test Signing Identity"),
        "verification subject: {}",
        verification.signer_subject()
    );

    // Flip one byte inside the first signed range. The CMS signature still
    // parses, but the covered digest no longer matches.
    let mut tampered = saved.clone();
    let index = contents_start / 2;
    assert!(index > 0, "the signed range must contain a middle byte");
    tampered[index] ^= 0xff;
    let tampered_verification =
        verify_signature(&tampered).expect("the tampered signature must still parse");
    assert_eq!(
        tampered_verification.status(),
        SignatureStatus::Tampered,
        "flipping byte {index} inside the signed range must be detected"
    );
    assert!(tampered_verification.signature_valid());
    assert!(!tampered_verification.bytes_match());
}
